       })
       .setOrigin(0.5, 0);

     let playerName = "Hero";
     const nameInputReadyAt = performance.now() + 75;
     const nameText = this.add
       .text(cx, nameLabel.y + nameLabel.height + 3, playerName, {
         fontSize: "18px",
         fontFamily: "monospace",
         color: "#fff",
