     PLAYER_CLASSES.forEach((app, i) => {
       const ox = startX + (i % cols) * optW;
       const oy = startY + Math.floor(i / cols) * optH;
       const hitZone = this.add.zone(ox, oy + 10, 56, 62).setInteractive({ useHandCursor: true });
       hitZone.on("pointerdown", () => {
