         allowOverlapWith: ["button"],
       },
     ], { x: 0, y: 0, width: 100, height: 60 });
     expect(result.overlaps.map(({ firstId, secondId }) => [
       firstId,
       secondId,
     ])).toEqual([["title", "button"]]);
     expect(result.clipping.map((entry) => entry.id)).toEqual(["tooltip"]);
   });
 });

