+  const rowCount = Math.ceil(count / columnCount);
+  const offset = direction === "up" ? -1 : 1;
+  for (let distance = 1; distance <= rowCount; distance += 1) {
+    const nextRow = (row + offset * distance + rowCount) % rowCount;
