         || nextCost === undefined
         || nextCost - currentCost > remaining
       ) {
         return;
       }
       currentStats[key] += 1;
       renderStats();
     };
     this.bindCharacterCreationControls({
       up: () => moveStatSelection("up"),
       down: () => moveStatSelection("down"),
       left: () => adjustSelectedStat(-1),
       right: () => adjustSelectedStat(1),
       confirm: goNext,
       cancel: goBack,
     });
   }

